--- 해당 기능을 사용하지 않으면 지워도 무관함
function local_class:on_pre_load()
	screen_util.preload_tutorial_spine()

	self.fx:load_all()
end

--- 해당 기능을 사용하지 않으면 지워도 무관함
function local_class:need_skip()
	return false
end

function local_class:enter()
	self:set_pre_npc()

	self:set_current_scene_npc_data()
end

function local_class:start()
	message_system:Subscribe(self, typeof(CS.Oak.InteractEvent), 'on_event')
	message_system:Subscribe(self, typeof(CS.Oak.ZoneEnterEvent), 'on_zone_enter_event')
	message_system:Subscribe(self, typeof(CS.Oak.BattleStartEvent), 'on_battle_start_event')
	message_system:Subscribe(self, typeof(CS.Oak.BattleGroupEliminatedEvent), 'on_battle_group_eliminated_event')
	message_system:Subscribe(self, typeof(CS.Oak.ExitInteractTeleportStartEvent), 'on_exit_interact_teleport_start_event')

	quest_marker_util.add_quest_marker_to_ifo(self.controller.quest_marker_name, self.controller.quest_id, true,
			self.field_object.area_in_exit())
end

function local_class:exit()
	message_system:Unsubscribe(self, typeof(CS.Oak.InteractEvent))
	message_system:Unsubscribe(self, typeof(CS.Oak.ZoneEnterEvent))
	message_system:Unsubscribe(self, typeof(CS.Oak.BattleStartEvent))
	message_system:Unsubscribe(self, typeof(CS.Oak.BattleGroupEliminatedEvent))
	message_system:Unsubscribe(self, typeof(CS.Oak.ExitInteractTeleportStartEvent))

	if self.fx ~= nil then
		self.fx:dispose()
	end

	if self.amb_1_sfx ~= nil then
		self.amb_1_sfx:Stop()
		self.amb_1_sfx = nil
	end

	if self.amb_2_sfx ~= nil then
		self.amb_2_sfx:Stop()
		self.amb_2_sfx = nil
	end

	quest_marker_util.remove(self.controller.quest_marker_name)

	if self.dyn_labose_creatures ~= nil then
		self.dyn_labose_creatures:dispose()
	end
end

function local_class:dispose()
	self.controller = nil
	self.cs_controller = nil
end

function local_class:on_event(e)
	if lua_helper.type_compare(e, CS.Oak.InteractEvent) then
		return self:on_interact_event(e)
	end

	return false
end

function local_class:on_interact_event(e)
	return false
end

function local_class:on_exit_interact_teleport_start_event(e)
	if e.ExitHandleName == 'building_in_1' or e.ExitHandleName == 'building_in_2' then
		start_coroutine(self.set_next_quest_marker, self, 'field_object', self.field_object.building_out_exit(2))

		return true
	elseif e.ExitHandleName == 'building_out_1' then
		start_coroutine(self.set_next_quest_marker, self, 'field_object', self.field_object.building_out_exit(1))

		return true
	elseif e.ExitHandleName == 'building_out_2' then
		if self.current_state < self.states.watch_labose_creatures_in_the_corner then
			start_coroutine(self.set_next_quest_marker, self, 'point', self.markers.check_labose_group_area_center())

			return true
		end
	end

	if e.ExitHandleName == 's8_area_in' then
		start_coroutine(self.set_next_quest_marker, self, 'field_object', self.field_object.building_in_exit(1))

		return true
	elseif e.ExitHandleName == 's8_area_out' then
		start_coroutine(self.set_next_quest_marker, self, 'field_object', self.field_object.area_in_exit())

		return true
	end

	return false
end

function local_class:on_zone_enter_event(e)
	local leader = get_party_leader()

	if type_util.is_zone_full_enter(e, leader, self.event_zone_names.battle_zone_1) and
			self.current_state == self.states.none and
			not self.battle_zone_enter[self.event_zone_names.battle_zone_1] then

		self.battle_zone_enter[self.event_zone_names.battle_zone_1] = true
	elseif type_util.is_zone_full_enter(e, leader, self.event_zone_names.battle_zone_2) and
				self.current_state == self.states.passing_heavenhold_route_2 and
			not self.battle_zone_enter[self.event_zone_names.battle_zone_2] then

		self.battle_zone_enter[self.event_zone_names.battle_zone_2] = true
	elseif type_util.is_zone_full_enter(e, leader, self.event_zone_names.battle_zone_3) and
				self.current_state == self.states.passing_heavenhold_route_3 and
			not self.battle_zone_enter[self.event_zone_names.battle_zone_3] then

		start_coroutine(self.change_custom_bgm_setting, self)

		self.battle_zone_enter[self.event_zone_names.battle_zone_3] = true
	elseif type_util.is_zone_full_enter(e, leader, self.event_zone_names.battle_zone_4) and
			self.current_state == self.states.passing_heavenhold_route_4 and
			not self.battle_zone_enter[self.event_zone_names.battle_zone_4] then

		self.battle_zone_enter[self.event_zone_names.battle_zone_4] = true
	elseif type_util.is_zone_full_enter(e, leader, self.event_zone_names.watch_road) and
				self.current_state == self.states.passing_heavenhold_route_1 then
		-- 옥상 이벤트
		self.controller.sp_manager:start_scene_delayed(self.play_watch_labose_creatures_on_the_rooftop_event, self)
	elseif type_util.is_zone_full_enter(e, leader, self.event_zone_names.check_labose_group) and
				self.current_state == self.states.passing_heavenhold_route_2 then
		-- 길 모퉁이 진입 이벤트
		self.controller.sp_manager:start_scene_delayed(self.play_watch_labose_creatures_in_the_corner_event, self)
	elseif type_util.is_zone_full_enter(e, leader, self.event_zone_names.destroying_police_car) and
				self.current_state == self.states.passing_heavenhold_route_3 then
	end

	return true
end

function local_class:on_battle_start_event(e)
	if e ~= nil and e.StartedBattle ~= nil then
		self.current_started_battle = e.StartedBattle
	end
end

function local_class:on_battle_group_eliminated_event(e)
	self.current_started_battle = nil

	if e.BattleGroupName == 's8_battle_1' then
		self.current_state = self.states.passing_heavenhold_route_1
	elseif e.BattleGroupName == 's8_battle_3' then
		self.current_state = self.states.passing_heavenhold_route_4
	elseif e.BattleGroupName == 's8_battle_4' then
		self.controller.sp_manager:start_scene_delayed(self.enter_last_scene, self)
	elseif e.BattleGroupName == 's8_battle_5' then
		start_coroutine(self.section_end, self)
	end

	return false
end

--region quest marker
function local_class:set_next_quest_marker(marker_type, marker_point)
	quest_marker_util.remove(self.controller.quest_marker_name)

	wait_for_sec(0.35)

	if marker_type == 'field_object' then
		quest_marker_util.add_quest_marker_to_ifo(self.controller.quest_marker_name, self.controller.quest_id, true,
				marker_point)
	elseif marker_type == 'point' then
		quest_marker_util.add_quest_marker_to_point(self.controller.quest_marker_name, self.controller.quest_id, true,
				marker_point)
	end
end
--endregion

