function local_class:set_all_npc_battle_state(npc)
	if lua_helper.type_compare(npc.FieldObjectController.CurrentState, CS.Oak.IBattleAIState) then

		return
	end

	if npc.CharacterBehaviour.BattleStyleSpec == nil then
		return
	end

	local ai_name = npc.CharacterBehaviour.BattleStyleSpec.BattleAI;

	if ai_name == nil then
		return
	end

	local battle_state = CS.Oak.BattleAIStateFactory.Create(ai_name, npc, nil)

	message_system:SendSync(npc.FieldObjectController, CS.Oak.StateChangeEvent.Create(battle_state))
end

-- 동적 할당된 라보스 크리쳐들 셋팅
function local_class:pre_setting_dyn_lasbose_in_current_state_scene(state, remove_char_stat_ui)
	local ogres = self.dyn_labose_creatures.ogres
	local soldiers = self.dyn_labose_creatures.soldiers
	local fighters = self.dyn_labose_creatures.fighters
	local soldier_count = 0
	local fighter_count = 0

	remove_char_stat_ui = lua_helper.get_or_default(remove_char_stat_ui, false)

	table_util.for_each(soldiers, function(i, labose_creature)
		local pre_npc_data = self.pre_npc_data[state]

		if pre_npc_data ~= nil then
			local num_text = string.match(i, '%d+$')
			local num = tonumber(num_text)

			character_util.set_position(labose_creature, pre_npc_data[num].pos)

			scene_util.set_direction(labose_creature, pre_npc_data[num].dir, false)

			if remove_char_stat_ui then
				field_ui_manager:RemoveUI(labose_creature, CS.Oak.FieldUiType.CharacterStats)
			end

			soldier_count = soldier_count + 1
		end
	end)

	table_util.for_each(fighters, function(i, labose_creature)
		local pre_npc_data = self.pre_npc_data[state]

		if pre_npc_data ~= nil then
			local num_text = string.match(i, '%d+$')
			local num = tonumber(num_text)
			local modify_npc_index = num + soldier_count

			character_util.set_position(labose_creature, pre_npc_data[modify_npc_index].pos)

			scene_util.set_direction(labose_creature, pre_npc_data[modify_npc_index].dir, false)

			if remove_char_stat_ui then
				field_ui_manager:RemoveUI(labose_creature, CS.Oak.FieldUiType.CharacterStats)
			end

			fighter_count = fighter_count + 1
		end
	end)

	table_util.for_each(ogres, function(i, labose_creature)
		local pre_npc_data = self.pre_npc_data[state]

		if pre_npc_data ~= nil then
			local num_text = string.match(i, '%d+$')
			local num = tonumber(num_text)
			local big_npc_index = num + soldier_count + fighter_count

			character_util.set_position(labose_creature, pre_npc_data[big_npc_index].pos)

			scene_util.set_direction(labose_creature, pre_npc_data[big_npc_index].dir, false)

			if remove_char_stat_ui then
				field_ui_manager:RemoveUI(labose_creature, CS.Oak.FieldUiType.CharacterStats)
			end
		end
	end)
end

function local_class:clear_s8_battle_1_event()
	sp_util.start_scene(self.play_post_first_event, self)
end

function local_class:play_post_first_event()
	self.current_state = self.states.after_the_first_battle

	local knight = user_party.Leader
	local queen = self.characters.demon_queen()
	local engineer = self.characters.demon_engineer()

	screen_util.fade_out_async(0.5, unity_class.color.black, 'linear')

	wait_for_sec(0.25)

	while not self.is_soldier_entry_action_completed do
		coroutine.yield(nil)
	end

	wait_for_sec(0.5)

	character_util.set_position(knight, self.markers.knight(1, 1))
	scene_util.set_direction(knight, 'right', false)

	character_util.set_position(queen, self.markers.demon_queen(1, 1))
	scene_util.set_direction(queen, 'right', false)
	scene_util.set_emotion(queen, self, 'tired')

	character_util.set_position(engineer, self.markers.demon_engineer(1, 1))
	scene_util.set_direction(engineer, 'right', false)

	camera_util.move_async(queen.Position + vector(1, 0, 0), 0)

	wait_for_sec(0.5)

	screen_util.fade_in_async(0.5, unity_class.color.black, 'linear')

	-- 경찰1 : 리리스 각하께 경례!

	-- 경찰1 ~ 6 전원 (attack, salute, 루프 없이, shout 말풍선, 스킵 불가능, 크기 2배) : 충성!

	-- 리리스(sleep_deep, nod 1회) : 도와줘서 고마워.
	scene_util.play_normal_speech_action(queen, self,
			nil,
			{ name = 'nod', count = 1 },
			{ name = 'sleep_deep' },
			{ key = 'lw_main_s8_1_4', skip = true })

	-- 경찰 1 ~ 6 전원 attack, idle로 전환.

	-- 리리스(tired, bomb_idle) : 연락이 닿은 다른 소대는… 없어?
	scene_util.play_normal_speech_action(queen, self,
			nil,
			{ name = 'bomb_idle' },
			{ name = 'tired', keep = true },
			{ key = 'lw_main_s8_1_5', skip = true })

	-- 경찰1(left, idle) : 다른 소대들은 연락이 되지 않습니다.

	-- 리리스(sleep_deep, nod 1회) : …….
	scene_util.play_normal_speech_action(queen, self,
			nil,
			{ name = 'nod', count = 1 },
			{ name = 'sleep_deep' },
			{ key = 'lw_main_s8_1_7', skip = true })

	scene_util.set_emotion(queen, self, 'tired')

	-- 비네트(attack, bomb_idle) : 무전으로도 전달했지만, 우리는 헤븐홀드로 가고 있어.
	scene_util.play_normal_speech_action(engineer, self,
			nil,
			{ name = 'bomb_idle' },
			{ name = 'attack', keep = true },
			{ key = 'lw_main_s8_1_8', skip = true })

	-- 비네트(attack, cast) : 헤븐홀드로 가는 길을 터줄 수 있겠어?
	scene_util.play_normal_speech_action(engineer, self,
			nil,
			{ name = 'cast' },
			{ name = 'attack', keep = true },
			{ key = 'lw_main_s8_1_9', skip = true })

	-- 비네트(attack, cast2) : 헤븐홀드가 이 사태를 막을 유일한 희망이야.
	scene_util.play_normal_speech_action(engineer, self,
			nil,
			{ name = 'cast2' },
			nil,
			{ key = 'lw_main_s8_1_10', skip = true })

	-- 경찰1 : 실례지만 누구신지…

	-- 가디언 선택지
	local choose_result = choose_util.play_choose_event({
		{ 'lw_main_s8_1_12', 'mercy' }, { 'lw_main_s8_1_13', 'intellect' } })

	if choose_result == 1 then
		-- 마계의 영웅인 내 부탁이다!(초록)
		-- 가디언 sleep_deep, bomb_idle 1초
		scene_util.play_wait_action(knight, self,
				nil,
				{ name = 'bomb_idle' },
				{ name = 'sleep_deep' },
				1)

		wait_for_sec(0.1)

		-- 가디언 attack, victory_get 1회
		character_util.hide_weapon(knight, false)
		scene_util.show_victory_get_async(knight, self, { emotion = 'attack', dir = 'right', end_delay = 0.8 })
		character_util.hide_weapon(knight, true)

		-- 경찰1 : 마계의 영웅님!
	elseif choose_result == 2 then
		-- 나, $name도 부탁하지!(노랑)
		-- 가디언 attack, salute_china 1회, 1초대기.
		scene_util.play_wait_action(knight, self,
				nil,
				{ name = 'salute_china', loop = false },
				{ name = 'attack' },
				1)
	end

	-- 경찰1 ~ 6 전원 attack, salute, 루프 없이

	-- 화면 우측 중앙, shout 말풍선, 카메라 shake 0.3초, 세기 0.15 : 알겠습니다!

	-- 1초 대기
	wait_for_sec(1)

	-- 리리스(right, tired, idle) : 비네트, 헤븐홀드는…
	scene_util.play_normal_speech_action(queen, self,
			{ dir = 'right', sfx = false },
			nil,
			{ name = 'tired', keep = true },
			{ key = 'lw_main_s8_1_17', skip = true })

	-- 비네트(attack, nod 1회) : 그래도 아직까지는 어떻게든 버티고 있는 것 같아.
	scene_util.play_normal_speech_action(engineer, self,
			nil,
			{ name = 'nod', count = 1 },
			{ name = 'attack' },
			{ key = 'lw_main_s8_1_18', skip = true })

	-- 비네트(attack, bomb_idle) : 어서 이동하자.
	scene_util.play_normal_speech_action(engineer, self,
			nil,
			{ name = 'bomb_idle' },
			{ name = 'attack' },
			{ key = 'lw_main_s8_1_19', skip = true })

	camera_util.return_to_leader(1)

	party_util.remove_animation()
	party_util.remove_emotion()

	-- 컨트롤 해제한 이후에도 리리스 표정 tired로.
	scene_util.set_emotion(queen, self, 'tired')

	-- 씬 상태 변경 및 씬에서 사용될 다이나믹 npc 생성
	self.current_state = self.states.passing_heavenhold_route_1

	-- 다음 씬 npc 셋팅
	self.dyn_labose_creatures:load_async(self.states.watch_labose_creatures_on_the_brigde)
	self:pre_setting_dyn_lasbose_in_current_state_scene(self.states.watch_labose_creatures_on_the_brigde, true)

end

function local_class:play_watch_labose_creatures_on_the_rooftop_event()
	self.current_state = self.states.watch_labose_creatures_on_the_brigde

	-- w18_city_robot은 항상 켜져있지 않고, 본 연출 시작했을 때에만 켜져 있도록 처리 필요.

	music_player_util.change_stage_music_volume('field', 0.6)

	local knight = user_party.Leader
	local queen = self.characters.demon_queen()
	local engineer = self.characters.demon_engineer()
	local move_duration = 1
	local move_speed = 5

	-- 존 엔터하면 이벤트 진행.
	-- 1초간 일행 전원 정해진 위치로 정렬.
	-- 전원 up 방향 바라본다.
	wp_util.move(knight, self.markers.knight(2, 1), nil, move_duration, { last_direction = 'up' })

	wp_util.move(queen, self.markers.demon_queen(2, 1), nil, move_duration, { last_direction = 'up' })

	wp_util.move(engineer, self.markers.demon_engineer(2, 1), nil, move_duration, { last_direction = 'up' })

	for i = 0, user_party.Count - 1 do
		user_party[i].SpineController:SetSortingLayer('Top Effects', 100)
	end

	wait_for_sec(move_duration)

	-- 0.5초 대기
	wait_for_sec(0.5)

	-- 카메라 shake 1초간 세기 0.15 - 가능하면 헤븐홀드와 싸우고 있는 거대 괴물의 울음소리 삽입
	music_player_util.play_sfx_one_shot('02_stomp_fire_02')
	camera_util.shake(0.15, 1)

	wait_for_sec(1)

	-- 리리스(up, idle) : 저… 저건…
	scene_util.play_normal_speech_action(queen, self,
			nil,
			nil,
			nil,
			{ key = 'lw_main_s8_1_1', skip = true })

	-- 로봇-괴물 구도 카메라 이동과 함께 환경음 볼륨 0.7로 루프 재생, 믹스 3초
	self.amb_1_sfx = music_player_util.play_sfx({ sfx_name = '01_war_loop_01', fade_in_time = 3, volume = 0.7, loop = true, type_priority = 'event' })

	-- 카메라 움직이기 시작 전까지 루프 재생, 카메라 이동 시 믹스 1초로 종료 부탁드립니다.
	self.amb_2_sfx = music_player_util.play_sfx({ sfx_name = '02_harvester_thunder_01', volume = 0.3, loop = true })

	-- 카메라 1.5초간 z축 회전 값 20도로 변경. - 원경연출 부분.
	-- 동시에 1.5초간 카메라 포커스 15칸 위로 이동.
	local pos_param = {}
	local angle_param = {}

	self:add_camera_param(pos_param, 0, vector(0, 0, 20), 1.5)
	self:add_camera_param(angle_param, 0, vector(20, 0, 0), 1.5)

	self:camera_move_by_param({ pos = pos_param, duration = 1.5, angle = angle_param })

	-- 5초 대기
	wait_for_sec(5)

	pos_param = {}
	angle_param = {}

	-- 로봇-괴물 구도 다시 이동과 함꼐 환경음 볼륨 0.4으로 조절, 믹스 디폴트값
	if self.amb_1_sfx ~= nil then
		self.amb_1_sfx:ChangeVolume(0.4)
	end

	if self.amb_2_sfx ~= nil then
		self.amb_2_sfx:FadeOut(1)
		self.amb_2_sfx = nil
	end

	-- 카메라 1.5초간 z축 회전 값 45도로 변경
	-- 동시에 1.5초간 카메라 포커스 기사에게로 복귀.
	self:add_camera_param(pos_param, 0, vector(0, 0, -20), 1.5)
	self:add_camera_param(angle_param, 0, vector(45, 0, 0), 1.5)

	self:camera_move_by_param({ pos = pos_param, duration = 1.5, angle = angle_param })

	for i = 0, user_party.Count - 1 do
		user_party[i].SpineController:SetSortingLayer('Default', 0)
	end

	-- 리리스(up, idle) : 헤븐홀드가… 쓰러졌어…?
	scene_util.play_normal_speech_action(queen, self,
			nil,
			nil,
			nil,
			{ key = 'lw_main_s8_1_2', skip = true })

	-- 비네트(up, idle, shake 0.3초) : 한계가 온 건가…
	music_player_util.play_sfx_one_shot('01_rustle_01')
	character_util.shake(engineer, 0.03, 0.3)
	scene_util.play_normal_speech_action(engineer, self,
			nil,
			nil,
			nil,
			{ key = 'lw_main_s8_1_3', skip = true })

	-- 비네트 제외 전원 left로.
	-- 리리스 tired로 유지.
	scene_util.set_emotion(queen, self, 'tired')
	scene_util.set_direction(knight, 'left', false)
	scene_util.set_direction(queen, 'left', false)

	-- 비네트(right, attack, dagger_idle) : 이대로면 내부까지 괴물들이 침투할 거야.
	scene_util.play_normal_speech_action(engineer, self,
			{ dir = 'right', sfx = false },
			{ name = 'dagger_idle', one_shot_sfx = '01_swing_01', keep = true },
			{ name = 'attack', keep = true },
			{ key = 'lw_main_s8_1_4', skip = true })

	-- 마계 경찰은 up 유지.

	-- 비네트(right, attack, release) : 더 늦으면 내부에서부터 망가질지도 몰라.
	scene_util.play_normal_speech_action(engineer, self,
			{ dir = 'right', sfx = false },
			{ name = 'release' },
			nil,
			{ key = 'lw_main_s8_1_5', skip = true })

	-- 기사 right로 전환.
	scene_util.set_direction(knight, 'right', false)

	-- 리리스(left, tired, idle) : 헤븐홀드마저 빼앗기면…
	scene_util.play_normal_speech_action(queen, self,
			{ dir = 'left', sfx = false },
			nil,
			{ name = 'tired', keep = true },
			{ key = 'lw_main_s8_1_6', skip = true })

	-- 비네트(attack, dagger_idle) : 네 말대로 마계는 버려야 할지도 모르지.
	scene_util.play_normal_speech_action(engineer, self,
			nil,
			{ name = 'dagger_idle', keep = true },
			{ name = 'attack', keep = true },
			{ key = 'lw_main_s8_1_7', skip = true })

	-- 리리스(tired, cast) : 그건….
	scene_util.play_normal_speech_action(queen, self,
			nil,
			{ name = 'cast', one_shot_sfx = '01_rustle_01', keep = true },
			{ name = 'tired', keep = true },
			{ key = 'lw_main_s8_1_8', skip = true })

	-- 비네트(right, attack, idle) : 더 서두르자.
	scene_util.play_normal_speech_action(engineer, self,
			{ dir = 'right', sfx = false },
			{ name = 'idle', keep = true },
			{ name = 'attack', keep = true },
			{ key = 'lw_main_s8_1_9', skip = true })

	-- 퀘스트 마커는 라보스 괴물 확인하는 장소로.

	camera_util.cancel_shake()

	camera_util.return_to_leader(1)

	party_util.remove_animation()
	party_util.remove_emotion()

	scene_util.set_emotion(queen, self, 'tired')

	self.current_state = self.states.passing_heavenhold_route_2

	if self.amb_1_sfx ~= nil then
		self.amb_1_sfx:FadeOut(4)
		self.amb_1_sfx = nil
	end

	music_player_util.change_stage_music_volume('field', 1)
end

function local_class:play_watch_labose_creatures_in_the_corner_event()
	local knight = user_party.Leader
	local queen = self.characters.demon_queen()
	local engineer = self.characters.demon_engineer()
	local move_duration = 2

	quest_marker_util.remove(self.controller.quest_marker_name)

	self.current_state = self.states.watch_labose_creatures_in_the_corner

	self.dyn_labose_creatures:load_async(self.states.watch_labose_creatures_in_the_corner)
	self:pre_setting_dyn_lasbose_in_current_state_scene(self.states.watch_labose_creatures_in_the_corner)

	party_util.set_emotion({ name = 'attack' })

	-- 존 엔터하면 이벤트 진행.
	-- 1초간 일행 전원 정해진 위치로 정렬.
	-- 전원 up 방향 바라본다.
	wp_util.move(knight, self.markers.knight(3, 1), nil, move_duration, { last_direction = 'left' })

	wp_util.move(queen, self.markers.demon_queen(3, 1), nil, move_duration, { last_direction = 'left' })

	wp_util.move(engineer, self.markers.demon_engineer(3, 1), nil, move_duration, { last_direction = 'left' })

	camera_util.move(self.markers.check_labose_group_area_center(), move_duration)

	wait_for_sec(move_duration)

	music_player_util.play_stage_music({ state = 'muted', mix = 10 })

	-- 비네트 left, attack, idle, jump 1회 느낌표 이모티콘
	music_player_util.play_sfx_one_shot('03_dialogue_notice_01')
	character_util.normal_jump(engineer, true)
	scene_util.play_emoticon_action(engineer, self, 'left', nil, 'attack', 'notice')

	-- 비네트 (left, attack, release) : 저… 저기를 봐!
	scene_util.play_normal_speech_action(engineer, self,
			{ dir = 'left', sfx = false },
			{ name = 'release' },
			{ name = 'attack', keep = true },
			{ key = 'lw_main_s8_2_1', skip = true })

	-- 카메라 이동 시작과 동시에 일행 1초만에 전원 정렬 위치 변경한다.
	local party_arrive_pos_list = {
		[knight.Name] = self.markers.knight(3, 2),
		[queen.Name] = self.markers.demon_queen(3, 2),
		[engineer.Name] = self.markers.demon_engineer(3, 2),
	}

	wp_util.move(knight, self.markers.knight(3, 2),
			nil, move_duration,
			{ run = true, last_direction = 'left' })

	wp_util.move(queen, self.markers.demon_queen(3, 2),
			nil, move_duration,
			{ run = true, last_direction = 'left' })

	wp_util.move(engineer, self.markers.demon_engineer(3, 2),
			nil, move_duration,
			{ run = true, last_direction = 'left' })

	wait_for_sec(0.25)

	-- 카메라 포커스 아래의 연두색 마름모로 5초만에 이동.
	-- 카메라 이동과 함께 BGM 재생, 믹스 6초
	music_player_util.play_stage_music({name = 'ondemand/v2_15_demonworld/audio:bgm_demonworld_event_8', state = 'event', mix = 6})
	camera_util.move_async(self.markers.cross_road_center(), 5)

	-- 3초 대기
	wait_for_sec(3)

	-- 카메라 이동 시작부터 리리스 표정 tired
	scene_util.set_emotion(queen, self, 'tired')

	-- 이후 카메라 5초에 걸쳐서 다시 비네트에게로 복귀.
	camera_util.move_async(engineer.Position, 5)

	-- 비네트(left, attack, idle) : 그냥 지나갈 수는 없겠는데.
	scene_util.play_normal_speech_action(engineer, self,
			{ dir = 'left', sfx = false },
			nil,
			{ name = 'attack', keep = false },
			{ key = 'lw_main_s8_2_2', skip = true })

	-- 리리스(left, tired, cast) : 비네트. 다른 길을 찾아보는 게…
	--이후에도 표정 tired.
	scene_util.play_normal_speech_action(queen, self,
			nil,
			{ name = 'cast', keep = true },
			{ name = 'tired', keep = true },
			{ key = 'lw_main_s8_2_3', skip = true })

	-- 비네트(left, sleep_deep, idle) : 아니. 그럴 시간 없어.
	scene_util.play_normal_speech_action(engineer, self,
			{ dir = 'left', sfx = false },
			nil,
			{ name = 'sleep_deep' },
			{ key = 'lw_main_s8_2_4', skip = true })

	-- 비네트(left, attack, dagger_idle) : 반드시 이곳을 뚫어내야 해.
	scene_util.play_normal_speech_action(engineer, self,
			{ dir = 'left', sfx = false },
			{ name = 'dagger_idle', one_shot_sfx = '03_dialogue_ready_01', keep = true },
			{ name = 'attack', keep = true },
			{ key = 'lw_main_s8_2_5', skip = true })

	-- 가디언 선택지
	local choose_result = choose_util.play_choose_event({
		{ 'lw_main_s8_2_6', 'mercy' }, { 'lw_main_s8_2_7', 'forced' } })

	if choose_result == 1 then
		-- 앗, 라보스 괴물과 싸우면 죽는 병이…(보라)

		-- 가디언 damaged, dead1 루프 없이 실행, 이후 자세 유지.
		music_player_util.play_sfx_one_shot('03_dialogue_negative_01')
		local anim_duration = spine_util.get_animation_duration(knight, 'dead1')
		scene_util.set_emotion(knight, self, 'damaged')
		scene_util.set_anim(knight, self, { name = 'dead1', sfx_name = '01_hit_npc_01', loop = false })

		wait_for_sec(anim_duration * 1.15)

		-- 아래 대사 시작과 동시에 가디언 마리오 점프로 일어난다.
		start_coroutine(function()
			music_player_util.play_sfx_one_shot('01_player_popup_01')
			character_util.mario_jump_async(knight, knight.Direction)

			-- 이모션도 해제.
			character_util.remove_anim(knight)
			character_util.remove_emotion(knight)
		end)

		-- 비네트(tired, bomb_idle) : 그런 병은 없어… 뭐, 지면 죽기는 하겠지만.
		music_player_util.play_sfx_one_shot('03_dialogue_tipsy_01')
		scene_util.play_normal_speech_action(engineer, self,
				nil,
				{ name = 'bomb_idle' },
				{ name = 'tired' },
				{ key = 'lw_main_s8_2_8', skip = true })
	elseif choose_result == 2 then
		-- 내 사전에 포기란 없다!(초록)

		-- 가디언 attack, victory_get 1회
		character_util.hide_weapon(knight, false)
		scene_util.show_victory_get_async(knight, self, { emotion = 'attack', dir = 'left', end_delay = 0.8 })
		character_util.hide_weapon(knight, true)

		-- 비네트(attack, nod 1회) : 그래, 여기서 멈출 순 없어.
		scene_util.play_normal_speech_action(engineer, self,
				nil,
				{ name = 'nod', count = 1 },
				{ name = 'attack' },
				{ key = 'lw_main_s8_2_9', skip = true })
	end

	character_util.remove_anim(queen)

	-- 리리스(sleep_deep, idle): silence 이모티콘 출력
	scene_util.play_emoticon_action(queen, self, nil, nil, 'sleep_deep', 'silence')

	-- 리리스(attack, idle): …좋아, 가자.
	music_player_util.play_sfx_one_shot('03_dialogue_ready_01')
	scene_util.play_normal_speech_action(queen, self,
			nil,
			nil,
			{ name = 'attack', keep = true },
			{ key = 'lw_main_s8_2_10', skip = true })

	-- 리리스(attack, dagger_idle): 여기만 지나면… 앞으로 금방이야.
	scene_util.play_normal_speech_action(queen, self,
			nil,
			{ name = 'dagger_idle', keep = true },
			{ name = 'attack', keep = true },
			{ key = 'lw_main_s8_2_11', skip = true })

	-- 이후 리리스 표정 attack

	-- 가디언(attack, nod 2회) 끝날 때까지 대기
	scene_util.set_emotion(knight, self, 'attack')
	scene_util.set_anim_async(knight, self, { name = 'nod', count = 2 })

	camera_util.return_to_leader(1)

	party_util.remove_animation()
	party_util.remove_emotion()

	scene_util.set_emotion(queen, self, 'attack')

	scene_util.set_direction(user_party.Leader, 'left', false)

	music_player_util.change_stage_music_volume('field', 1)

	music_player_util.set_stage_music_clip_async(
			{ name = 'ondemand/v2_15_demonworld/audio:bgm_demonworld_hideout', state = 'combat' }
	)

	start_coroutine(self.set_next_quest_marker, self, 'point', self.markers.scene_5_labose_group_2_focus())

	self.current_state = self.states.passing_heavenhold_route_3
end

function local_class:event_battle_labose_creature_first_setting()
	self.chase_labose_creatures = {}

	for i = 1, self.chase_labose_creatures_count do
		local npc = self.characters.event_battle_labose_creature(4, i)

		character_util.set_active_state(npc, 'enabled')

		character_util.set_position(npc, self.markers.event_battle_labose_creature(i, 1, 1))

		scene_util.set_direction(npc, 'left', false)

		table.insert(self.chase_labose_creatures, npc)
	end
end

function local_class:move_event_battle_labose_creature(scene_pos_idx, speed, duration, offset_pos)
	offset_pos = lua_helper.get_or_default(offset_pos, unity_class.vector3.zero)

	for i = 1, self.chase_labose_creatures_count do
		local npc = self.characters.event_battle_labose_creature(4, i)

		logger_util.log('battle 4 NPC name : ' .. npc.Name)

		wp_util.move(npc, self.markers.event_battle_labose_creature(i, scene_pos_idx, 1) + offset_pos, speed, duration)
	end
end

function local_class:appear_second_wave_labose_creature()
	local labose = self.characters.event_battle_labose_creature(4, 4)
	local labose_pos = self.markers.event_battle_labose_creature(9, self.battle_4_enemy_pos_states.second_battle_wave, 1)

