function local_class:all_labose_group_move_to_center()
	-- 라보스 괴물들 위, 오른쪽, 아래쪽 순으로 각자 속도 1.3, 1.4, 0.8로 각자 중앙으로 2칸 이동한다.
	-- 오른쪽은 3칸 이동.
	local labose = nil
	local wp_key = 'all_labose_moving'
	local look_direction = nil
	local move_dist = nil
	local move_dist_list = { 3, 2, 2 }
	local move_speed = { 1.3, 1.4, 0.8 }
	local labose_group_count = 3


	for j = 1, labose_group_count do
		for i = 1, #self.scene_5_labose_creature[j].normal_list do
			labose = self.scene_5_labose_creature[j].normal_list[i]

			look_direction = character_util.get_look_direction(labose)
			move_dist = direction_util.to_vector3(look_direction) * move_dist_list[j]

			wp_util.move_with_end_callback(labose, labose.Position + move_dist, move_speed[j], nil, self, wp_key)
		end

		-- 오거 라보스
		--   오거는 charge 애니메이션으로 움직인다.
		for i = 1, #self.scene_5_labose_creature[j].ogre_list do
			labose = self.scene_5_labose_creature[j].ogre_list[i]

			look_direction = character_util.get_look_direction(labose)
			move_dist = direction_util.to_vector3(look_direction) * move_dist_list[j]

			wp_util.move_with_end_callback(labose, labose.Position + move_dist, move_speed[j], nil, self, wp_key)
		end
	end

	wp_util.wait_move_end(self, wp_key)
end

function local_class:wait_for_sec_to_stop(sec)
	local time_passed = 0
	while time_passed < sec do
		time_passed = time_passed + unity_class.time.deltaTime

		-- 모든 시간 기다리지 않고 탈출
		if self.loop_escape then
			return false
		end

		if self.current_state == self.states.breakthrough_labose_hordes then
			if self.is_destroyed_rock then
				return false
			end
		end

		coroutine.yield(nil)
	end

	-- 기다림 완료
	return true
end

function local_class:on_hit(move_info, hit_info, label)
	if hit_info == nil or hit_info.target == nil then
		return true
	end

	self.fx:half_vampire_explosion():Instantiate(hit_info.target.Position)

	if not self.is_half_vampire_proj_hit_ogre then
		self.is_half_vampire_proj_hit_ogre = true

		character_util.stop(hit_info.target)

		-- 이펙트에 맞는 순간
		-- 타임스케일 원상태로 복구.
		local slow_key = 'ogre_charge_dash'
		time_util.unmod(slow_key)

		-- 카메라 사이즈 4로 줌아웃.
		camera_util.resize_to_default(0.5)

		-- 카메라 shake 0.3초, 세기 0.2
		camera_util.shake(0.2, 0.3)
	end

	return true
end

function local_class:add_camera_param(params, delay, value, duration)
	local delay_val = lua_helper.get_or_default(delay, 0)
	local value_val = lua_helper.get_or_default(value, nil)
	local duration_val = lua_helper.get_or_default(duration, 0)

	table.insert(params, { delay = delay_val, value = value_val, duration = duration_val })
end

function local_class:camera_move_by_param(data)
	-- 카메라 위치
	local pos = lua_helper.get_value(data, 'pos', nil)

	-- 연출 시간
	local duration = lua_helper.get_value(data, 'duration', 0)

	-- 카메라 각도
	local angle = lua_helper.get_value(data, 'angle', nil)

	if pos ~= nil then
		start_coroutine(self.control_camera_pos, self, pos)
	end

	if angle ~= nil then
		start_coroutine(self.control_camera_angle, self, angle)
	end

	wait_for_sec(duration)
end

-- 카메라 회전 처리
function local_class:control_camera_angle(angle)
	for i = 1, #angle do
		local delay = lua_helper.get_value(angle[i], 'delay', 0)
		local value = lua_helper.get_value(
				angle[i], 'value', stage_camera.Transform.parent.localRotation.eulerAngles)
		local duration = lua_helper.get_value(angle[i], 'duration', 0)

		wait_for_sec(delay)

		local timer = 0
		local start_value = stage_camera.Transform.parent.localRotation.eulerAngles

		while timer < duration do
			timer = timer + unity_class.time.deltaTime

			local cur_value = unity_class.vector3.Lerp(start_value, value, timer / duration)
			stage_camera.Transform.parent.localRotation = unity_class.quaternion.Euler(cur_value)

			coroutine.yield(nil)
		end
	end
end

function local_class:control_camera_pos(pos)
	for i = 1, #pos do
		local delay = lua_helper.get_value(pos[i], 'delay', 0)
		local value = lua_helper.get_value(pos[i], 'value', 0)
		local duration = lua_helper.get_value(pos[i], 'duration', 0)

		wait_for_sec(delay)

		camera_util.move_async(stage_camera.LookAtPosition + value, duration)
	end
end

function local_class:ghost_buster_use_magiton()
	local ghost_buster = self.characters.ghost_buster()
	local target_list = {}
	local rock_count = 3
	for i = 1, rock_count do table.insert(target_list, get_field_object('s8_rock_' .. i)) end

	-- 마기톤 체인 스킬 상수 정의
	local shoot_duration = 1.5
	local shoot_max_count = 6
	local shoot_interval = shoot_duration / shoot_max_count
	local shoot_offset = 0.75

	local cast_time = 0.45
	music_player_util.play_sfx({sfx_name = '02_fox_ball_03'})
	-- 소히(right, attack, rifle_reload, loop = false, scale = 1.9) 캐릭터의 위치에 fx_cwp_magitonchain_ready 이펙트 생성
	scene_util.set_anim(ghost_buster, self, { name = 'rifle_reload', loop = false, scale = 1.9 })

	self.fx:ghost_buster_attack_ready():Instantiate(ghost_buster.Position)

	-- 0.45초 대기
	wait_for_sec(cast_time)

	-- 카메라 shake(0.1, 1.5)
	camera_util.shake(0.1, 1.5)

	-- 소히(right, attack, rifle_shoot2, scale = 1.9)
	scene_util.set_anim(ghost_buster, self, { name = 'rifle_shoot2', scale = 1.9 })

	-- 마키톤 체인 연출 루프
	local shoot_count = 0
	local time_passed = shoot_interval
	while shoot_count < shoot_max_count do
		time_passed = time_passed + unity_class.time.deltaTime

		if time_passed >= shoot_interval then
			shoot_count = shoot_count + 1

			if shoot_count == 1 then--if shoot_count == (shoot_max_count - 1) then
				music_player_util.play_sfx({ sfx_name = '02_impact_lightning_02' })
			end

			character_util.set_anim(ghost_buster, {name = 'rifle_shoot2', scale = 1.9})

			-- 소히가 인베이더들에게 마기톤 체인을 날림.
			local ghost_buster_shoot_point = ghost_buster.Position + direction_util.to_vector3(ghost_buster.Direction) * shoot_offset +
					unity_class.vector3.forward * 0.1
			local chain_indexes = { 1, 2, 3 }
			for i, target in pairs(target_list) do

				-- 앞 줄 인베이더들에게 붙는 체인
				if table_util.contain_value(chain_indexes, i) then
					local chain1 = self.fx:ghost_buster_attack_chain():Instantiate(ghost_buster_shoot_point)
					self:set_ray(chain1, ghost_buster_shoot_point, target.Position)
				end

				-- 각 히트 당하는 타겟들에게 붙는 체인
				if i ~= 1 then
					local chain2 = self.fx:ghost_buster_attack_chain():Instantiate(ghost_buster_shoot_point)
					self:set_ray(chain2, target_list[i - 1].Position, target.Position)
				end

				self.fx:ghost_buster_attack_fire():Instantiate(target.Position)
			end

			time_passed = 0
		end

		coroutine.yield()
	end

	-- 바위 오브젝트 모두 날려버림.
	-- 카메라 shake(0.4, 0.3)
	camera_util.shake(0.4, 0.3)

	-- fx_cwp_magitonchain 이펙트 생성 종료 / 잔해 제거 / 잔해 있던 위치에 FX_Env_BigRock_lv1_destroy 이펙트 생성
	for i = 1, rock_count do
		self.fx:rock_destroy():Instantiate(target_list[i].Position)

		target_list[i].ActiveState = active_state('disabled')
	end

	music_player_util.play_sfx_one_shot('03_rock_break_03')

	scene_util.set_emotion(ghost_buster, self, 'attack')
	scene_util.set_anim(ghost_buster, self, { name = 'rifle_idle' })

	wait_for_sec(1)
end

--- 소히 체인 라이트닝 이어붙여주는 함수
function local_class:set_ray(chain, start_point, target_point)
	local diff = vector_util.get_x0z(start_point - target_point)
	local rot = unity_class.quaternion.FromToRotation(unity_class.vector3.right, diff.normalized)
	local target_scale = diff.magnitude

	local scale_comp = chain:GetComponent(typeof(CS.Oak.ScalingEffect))
	scale_comp:SetTransform(target_point, rot, target_scale)
end

function local_class:custom_jump(target, height, duration, sfx)
	height = lua_helper.get_or_default(height, 0.5)
	duration = lua_helper.get_or_default(duration, 0.3)

	if sfx then
		if type(sfx) == 'string' then
			music_player:PlaySfxOneShot(sfx)
		else
			music_player:PlaySfxOneShot('01_small_jump_01')
		end
	end

	target:Jump(height, duration)
end

function local_class:change_custom_bgm_setting()
	wait_for_sec(1.1)

	coroutine.yield(nil)

	music_player_util.remove_stage_music_clip({ state = 'field' })

	stage.BattleManager.PlayBattleVoiceAndFanfare = false
end

return local_class
